__ht__function(json, dm, view, datas) {// ===== 基础初始化 =====
var view = graphView.getView();
var dm = graphView.dm();
graphView.setScrollBarVisible(false);

// ======================================================
// 🔥 表格更新（原逻辑保留）
function updateTable(payload, table) {
    if (!payload || !table) return;

    const {
        data: d = {},
        msgTime,
        furnaceCode,
        eventCode
    } = payload;

    const fullData = {
        ...d,
        msgTime,
        furnaceCode,
        eventCode
    };

    const fieldOrder = [
        'OutId2',
        'CardNo',
        'HeatNo',
        'SteelGrade',
        'OrderThick',
        'OrderLen',
        'TotalMatNum'
    ];

    fieldOrder.forEach((key, index) => {
        const node = table[index];
        if (node) node.a('ht.value', fullData[key] ?? '');
    });
}

let tableData1 ;
// 1. 定义轮询控制器（安全核心：可中断、防重复）
let pollingTimer = null;
let isRequesting = false; // 防重复请求关键

// 2. 轮询核心函数
async function startPolling(interval = 3000) {
  // 防止多次调用 startPolling 导致多轮询同时运行
  if (pollingTimer) return;

  // 递归执行轮询
  const execute = async () => {
    try {
      // 防重复：上一个请求没结束，不发新请求
      if (isRequesting) return;
      isRequesting = true;
    // 👇 你的接口请求
    request(`http://172.15.88.243:9003/api/bdy/bptdatcutopact/fetchcardinfo?ProductLine=H9`,{},'POST')
    .then(data => {
        tableData1 = data.Data;
        let table1 = graphView.dm().getDataByTag('1#plan');
        table1.a('ht.dataSource',tableData1);
    });
    } catch (err) {
      console.error("轮询异常：", err);
      // 安全：出错后不中断轮询，继续执行
    } finally {
      isRequesting = false; // 重置请求状态
      // 上一次请求结束后，再延迟指定时间发起下一次（绝对不堆积）
      pollingTimer = setTimeout(execute, interval);
    };
  };

  // 启动第一次
  execute();
}

// 3. 安全停止轮询（必须！防止内存泄漏）
function stopPolling() {
  if (pollingTimer) {
    clearTimeout(pollingTimer);
    pollingTimer = null;
  }
  isRequesting = false;
}

// ============= 使用方式 =============
startPolling(1000000); // 每3秒轮询一次
// stopPolling(); // 页面销毁/切换时必须调用}

