__ht__function(event, data, view) {// ============================================================
//  3#剪切台 — 锯片更换参数收集 & 校验
// ============================================================

// ===========================
// 1. 工具函数
// ===========================

/**
 * 获取当前日期时间字符串（精确到毫秒）
 * 格式：YYYY-MM-DD HH:mm:ss.SSS
 * @returns {string}
 */
function getCurrentTimeWithMs() {
    const date = new Date();

    // 日期部分
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');

    // 时间部分
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    const seconds = String(date.getSeconds()).padStart(2, '0');

    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

/**
 * 收集1#~3#锯的设定长度/实际位置/光栅位置/测量位置值
 * @returns {object} {Saw1LengthSetting: ..., Saw1ActualPosition: ..., ...}
 */
function getSawPositionValues() {
    var tags = [
        'Saw1LengthSetting', 'Saw1ActualPosition', 'Saw1GratingPosition', 'Saw1LengthActual',
        'Saw2LengthSetting', 'Saw2ActualPosition', 'Saw2GratingPosition', 'Saw2LengthActual',
        'Saw3LengthSetting', 'Saw3ActualPosition', 'Saw3GratingPosition', 'Saw3LengthActual'
    ];
    var result = {};
    tags.forEach(function(tag) {
        var node = dataModel.getDataByTag(tag);
        result[tag] = node ? Number(node.a('value')) : null;
    });
    return result;
}

/**
 * 校验请求参数完整性 & 数值有效性
 * @param {object} params - 待校验的参数对象
 * @returns {{ valid: boolean, errors: string[] }}
 */
function validateParams(params) {
    const requiredFields = [
        'CardNo', 'ProductLine', 'SawMachineNumber',
        'BladeChangeTime', 'OldBladeDiameter', 'NewBladeDiameter'
    ];
    //1-3#锯的设定长度/实际位置/光栅位置/测量位置字段
    const positionFields = [
        'Saw1LengthSetting', 'Saw1ActualPosition', 'Saw1GratingPosition', 'Saw1LengthActual',
        'Saw2LengthSetting', 'Saw2ActualPosition', 'Saw2GratingPosition', 'Saw2LengthActual',
        'Saw3LengthSetting', 'Saw3ActualPosition', 'Saw3GratingPosition', 'Saw3LengthActual'
    ];
    const allFields = requiredFields.concat(positionFields);
    const errors = [];

    // 非空校验
    allFields.forEach(function(field) {
        if (params[field] === null || params[field] === undefined || params[field] === '') {
            errors.push('参数 ' + field + ' 不能为空');
        }
    });

    // 锯片直径数值校验
    ['OldBladeDiameter', 'NewBladeDiameter'].forEach(function(field) {
        if (params[field] !== null && params[field] !== undefined && isNaN(Number(params[field]))) {
            errors.push('参数 ' + field + ' 必须为有效数值');
        }
    });

    // 锯位位置数值校验
    positionFields.forEach(function(field) {
        var val = params[field];
        if (val !== null && val !== undefined && val !== '' && isNaN(Number(val))) {
            errors.push('参数 ' + field + ' 必须为有效数值');
        }
    });

    if (errors.length > 0) {
        console.error('参数校验失败:', errors);
        return { valid: false, errors: errors };
    }
    return { valid: true, errors: [] };
}

// ===========================
// 2. 数据获取
// ===========================
//卡号信息
var cardNoTable = dataModel.getDataByTag('1#plan');
var cardNoInput = dataModel.getDataByTag('CardNo');
//卡号获取
var CardNo;
if(cardNoInput && cardNoInput.a('value')){
    CardNo = cardNoInput.a('value');
    showToast("输入框卡号获取成功",CardNo);
}else if(cardNoTable && cardNoTable.a('ht.dataSource')){
    var ds = cardNoTable.a('ht.dataSource');
    if (ds && ds.length > 0) CardNo = ds[0].CardNo;
    showToast("表格卡号获取成功",CardNo);
}
if(!CardNo){
    showToast("未获取到卡号");
}

// 锯位信息参数
var sawPosition = getSawPositionValues();

// 锯位选择（允许为空）
var btnGroupNode = dataModel.getDataByTag('SawMachineNumber');
var checkButton1 = btnGroupNode ? btnGroupNode.a('dataModel').toDatas(data => data.s('checked')).toArray() : [];

// 新旧锯片参数
var oldBlade = dataModel.getDataByTag('OldBladeDiameter');
var newBlade = dataModel.getDataByTag('NewBladeDiameter');

//生产班组信息
var group = dataModel.getDataByTag('Group');
var shift = dataModel.getDataByTag('Shift');
var selectMode = dataModel.getDataByTag('SelectMode');
var remark = dataModel.getDataByTag('Remark');
var checkButton2 = selectMode ? selectMode.a('dataModel').toDatas(data => data.s('checked')).toArray() : [];
console.log(checkButton1)

// ===========================
// 3. 参数拼接
// ===========================

var params = {
    CardNo: CardNo,
    ProductLine: "B1",
    SawMachineNumber: checkButton1.length > 0 ? checkButton1[0]._name : null,
    ProductionTime: getCurrentTimeWithMs(),
    BladeChangeTime: (oldBlade.a('value') || newBlade.a('value')) ? getCurrentTimeWithMs() : "",
    OldBladeDiameter: oldBlade.a('value'),
    NewBladeDiameter: newBlade.a('value'),
    ShiftGroup: group.a('value'),
    ShiftNo: shift.a('value'),
    ShearMethod: checkButton2.length > 0 ? checkButton2[0]._name : null,
    Memo: remark.a('value'),
    ...sawPosition
};
console.log(params)

// ===========================
// 4. 参数空值检查 & 弹窗确认提交
// ===========================

// 需检查的字段（排除时间、备注）
var checkFields = {
    'CardNo':                    '卡号',
    'ProductLine':               '产线',
    'SawMachineNumber':          '锯位',
    'OldBladeDiameter':          '旧锯片直径',
    'NewBladeDiameter':          '新锯片直径',
    'ShiftGroup':                '班组',
    'ShiftNo':                   '班次',
    'ShearMethod':               '剪切方式',
    'Saw1LengthSetting':         '1#锯设定值',
    'Saw1ActualPosition':        '1#锯实际位置',
    'Saw1GratingPosition':       '1#锯光栅位置',
    'Saw1LengthActual':          '1#锯测量位置',
    'Saw2LengthSetting':         '2#锯设定值',
    'Saw2ActualPosition':        '2#锯实际位置',
    'Saw2GratingPosition':       '2#锯光栅位置',
    'Saw2LengthActual':          '2#锯测量位置',
    'Saw3LengthSetting':         '3#锯设定值',
    'Saw3ActualPosition':        '3#锯实际位置',
    'Saw3GratingPosition':       '3#锯光栅位置',
    'Saw3LengthActual':          '3#锯测量位置'
};

var emptyFields = [];
for (var key in checkFields) {
    var v = params[key];
    if (v === null || v === undefined || v === '' || (typeof v === 'number' && isNaN(v))) {
        emptyFields.push(checkFields[key]);
    }
}

var confirmContent;
if (emptyFields.length > 0) {
    confirmContent = emptyFields.join('、') + "为空，是否提交？";
} else {
    confirmContent = "确认提交？";
}

DialogSystem.open({
    title: "提交确认",
    content: confirmContent,
    url: "http://172.15.88.243:9003/api/bdy/bptdatcutopact/create",
    params: params,
    requestFn: function(url, params) {
        return request(url, params, 'PUT');
    },
    onSuccess: function(result) {
        showToast("提交成功");
        // 接口操作成功后，刷新表格数据
        request('http://172.15.88.243:9003/api/bdy/bptdatcutopact/fetchcardinfo?ProductLine=B1', {}, 'POST')
        .then(function(data) {
            var table = dataModel.getDataByTag('1#plan');
            if (table && data && data.Data) {
                table.a('ht.dataSource', data.Data);
            }
        })
        .catch(function(err) {
            console.error('表格刷新失败:', err);
        });
    },
    onFail: function(error) {
        showToast("提交失败：" + error);
    }
});}
